# Backup first
find . -name "CMakeLists.txt" -exec cp {} {}.bak \;

# Replace SQLite3 with SQLite::SQLite3 in target_link_libraries
find . -name "CMakeLists.txt" -type f -exec sed -i 's/\(target_link_libraries([^)]*\) SQLite3/\1 SQLite::SQLite3/g' {} \;

get_service<mf_io_service>("asio").run_on_io([this]() {
                    // Begins the RPC system on the stream
                    _rpc.begin(_client);
                    /*
                     * Destroys the pending listener. reset forces the shared pointer to release the object in its memory and destroy it.
                     * We _need_ to do this because _pending will attempt to handle all network communications even though we are switching
                     * to a different system which handles that.
                     *
                     * We have to call this through run_on_main because we need to escape the invocation iteration which calls this event.
                     * This is because it will actually destroy the event handler and everything associated with it once invoked.
                     * If we do not delay this to the next run of the main master loop, it WILL cause errors on some platforms.
                     */
                    _pending.reset();
                    _rpc_ready(true);
                });
